/*! igtc-language-role-bridge.min.js (cleaned) */
(function(){
  'use strict';
  // Public Social pause: pre-paint the sidebar link in the five public hubs.
  // Runs synchronously in <head> before any sidebar markup is parsed.
  // Never changes the Admin sidebar, Social data, or country policies.
  var pageName = (location.pathname.split('/').pop() || '').toLowerCase();
  if (/^(?:home|networkhub|distributionhub|mediahub|tour)(?:_[a-z]{2,3})?(?:\.html)?$/.test(pageName)) {
    var earlyStyle = document.createElement('style');
    earlyStyle.id = 'igdc-social-public-sidebar-prepaint';
    earlyStyle.textContent = '.sidebar a[href*="socialnetwork" i]{display:none!important;pointer-events:none!important;}';
    (document.head || document.documentElement).appendChild(earlyStyle);
  }
  var LANG_ALIAS={'ko-kr':'ko','en-us':'en','zh-cn':'zh'};
  window.normalizeLang=function(code){
    if(!code) return 'en';
    code=code.toLowerCase();
    if(LANG_ALIAS[code]) return LANG_ALIAS[code];
    if(code.includes('-')) return code.split('-')[0];
    return code;
  };
  window.getUserRole=function(){
    try { return localStorage.getItem('user_role')||'guest'; }
    catch(_){ return 'guest'; }
  };
})();